-- ---------- Paper ----------
VALUES ('784390a2-01f9-4b4a-b907-73754dd200f5', 'terraform-hcp-workspaces-projects', 'Terraform Associate Practice: HCP Terraform Workspaces & Projects', 'terraform', ARRAY['Terraform Associate', 'HCP Terraform', 'Workspaces', 'Projects']::TEXT[], 38, 'advanced', true, 6, 60, 1, 0);

-- ── Section: Workspace Workflow Types & Execution Modes (10 questions) — Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material. ──

VALUES ('15eabab5-07d0-4cd1-9157-9abc56090e20', '784390a2-01f9-4b4a-b907-73754dd200f5', 1, 'In HCP Terraform''s VCS-driven workflow, what triggers a new run in a workspace?', 'Workspace Types', 'VCS-Driven Workflow', 'mcq');
VALUES ('15eabab5-07d0-4cd1-9157-9abc56090e20', '2ad45567-c7ea-4b3e-bdf7-1a15a80bcd6f', 'HCP Terraform registers a webhook with the VCS provider when a VCS-driven workspace is created; new commits to the linked branch automatically queue a run, no manual trigger needed.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('52d146fb-ad37-4533-b35e-f7fb514b3b05', '784390a2-01f9-4b4a-b907-73754dd200f5', 2, 'In a VCS-driven workspace, what happens when a pull request is opened against the workspace''s linked branch?', 'Workspace Types', 'VCS-Driven Speculative Plans', 'mcq');
VALUES ('52d146fb-ad37-4533-b35e-f7fb514b3b05', '78e6d29b-3b0f-48eb-979d-c11a78b6ba52', 'Speculative plans preview what a PR''s changes would do, posted directly on the PR, without ever proceeding to apply — they update automatically as the PR itself is updated.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('954b5b3f-9be1-43eb-b0d6-45947ffc68dc', '784390a2-01f9-4b4a-b907-73754dd200f5', 3, 'In the CLI-driven workflow, a practitioner runs ''terraform plan'' and ''terraform apply'' from their own terminal. Where does the actual Terraform execution happen?', 'Workspace Types', 'CLI-Driven Workflow', 'mcq');
VALUES ('954b5b3f-9be1-43eb-b0d6-45947ffc68dc', '0f3806b4-e0d2-43aa-bf0c-52c5ceb1e3a5', 'The CLI-driven workflow lets you keep using local `terraform` commands, but (in remote execution mode) the actual plan/apply runs remotely in HCP Terraform — your terminal is effectively a live view into that remote run.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('79acff84-f8f5-4b65-82de-10dfb2f0a082', '784390a2-01f9-4b4a-b907-73754dd200f5', 4, 'What two things does a practitioner typically need to set up before they can use the CLI-driven workflow against a specific HCP Terraform workspace?', 'Workspace Types', 'CLI-Driven Setup', 'mcq');
VALUES ('79acff84-f8f5-4b65-82de-10dfb2f0a082', 'ffa3f0ba-7cbc-4994-9ef7-fc50de9d6b5c', 'The CLI-driven workflow needs ''terraform login'' for authentication and a cloud block in configuration identifying the target HCP Terraform organization and workspace.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('158c5edf-a4b2-495a-9368-256dae1faf53', '784390a2-01f9-4b4a-b907-73754dd200f5', 5, 'What best characterizes the API-driven workflow, compared to VCS-driven and CLI-driven?', 'Workspace Types', 'API-Driven Workflow', 'mcq');
VALUES ('158c5edf-a4b2-495a-9368-256dae1faf53', 'ebcbf80a-5403-4f87-8721-9f03c0af9a04', 'API-driven is the most flexible workflow since runs are triggered by direct API calls rather than a VCS webhook or local CLI command, but that flexibility means you must build the integration/tooling yourself.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('d50ab5c0-ee23-45b5-8720-724e9e9f7cf4', '784390a2-01f9-4b4a-b907-73754dd200f5', 6, 'What does a workspace''s ''Remote'' execution mode mean?', 'Workspace Types', 'Remote Execution Mode', 'mcq');
VALUES ('d50ab5c0-ee23-45b5-8720-724e9e9f7cf4', '991fe087-2038-4292-8c08-879f7222e62a', 'Remote execution mode means HCP Terraform itself runs the operation on disposable infrastructure it manages, which is a prerequisite for features like Sentinel/OPA policy checks and cost estimation.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('e7b36919-0088-43f4-ba51-b5bd3c7c148a', '784390a2-01f9-4b4a-b907-73754dd200f5', 7, 'A workspace is set to ''Local'' execution mode. What is a specific documented limitation of this mode?', 'Workspace Types', 'Local Execution Mode Limitation', 'mcq');
VALUES ('e7b36919-0088-43f4-ba51-b5bd3c7c148a', 'e090a5a9-21c4-4b19-8a9a-20e510970999', 'In local execution mode, HCP Terraform still stores the workspace''s state, but it does NOT evaluate that workspace''s variables/variable sets — the run instead uses whatever the practitioner supplies locally.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('94cfa129-b835-4922-96f6-bc85b721cffe', '784390a2-01f9-4b4a-b907-73754dd200f5', 8, 'What is the purpose of a workspace''s ''Agent'' execution mode?', 'Workspace Types', 'Agent Execution Mode', 'mcq');
VALUES ('94cfa129-b835-4922-96f6-bc85b721cffe', '6eb7ac6e-665e-4b2b-b246-465deb5e270b', 'Agent execution mode routes runs through a self-hosted agent process, which is how HCP Terraform can operate against infrastructure in private networks that its own disposable cloud VMs can''t reach directly.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('92c6e83b-5bb9-4817-a3c0-88da156f3f8f', '784390a2-01f9-4b4a-b907-73754dd200f5', 9, 'How does triggering an auto-apply differ between the CLI-driven workflow and the UI/API/VCS-driven workflows?', 'Workspace Types', 'Auto-Apply: CLI vs. UI/API', 'mcq');
VALUES ('92c6e83b-5bb9-4817-a3c0-88da156f3f8f', 'f205d706-4821-463e-ada6-90974d2c9a58', 'CLI-driven applies need the practitioner to explicitly opt out of confirmation with -auto-approve, whereas UI/API-triggered runs defer to the workspace-level auto-apply configuration instead of a per-command flag.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('a1a73aaf-a152-431c-ae6d-da91c247ee17', '784390a2-01f9-4b4a-b907-73754dd200f5', 10, 'A team wants runs triggered entirely by their own custom internal deployment platform, with no direct VCS webhook and no one running Terraform CLI commands by hand. Which workflow type fits best?', 'Workspace Types', 'Choosing a Workflow Type', 'mcq');
VALUES ('a1a73aaf-a152-431c-ae6d-da91c247ee17', 'ee4869b8-6456-495b-806a-5e3762343a1d', 'API-driven is designed exactly for this: an external system (here, the team''s own deployment platform) drives runs directly through the API rather than relying on a VCS webhook or a human running CLI commands.', 'Workspace Workflow Types & Execution Modes — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/ui, .../run/cli, .../workspaces/settings, and hashicorp.com/blog/which-terraform-workflow-should-i-use-vcs-cli-or-api; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

-- ── Section: Projects: Organizing Workspaces (8 questions) — Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material. ──

VALUES ('73b5c2c3-b9aa-4b7e-b540-75cf037f718a', '784390a2-01f9-4b4a-b907-73754dd200f5', 11, 'How many projects can a single HCP Terraform workspace belong to at once?', 'Projects', 'Workspace-to-Project Relationship', 'mcq');
VALUES ('73b5c2c3-b9aa-4b7e-b540-75cf037f718a', '75a49c5c-a6da-4cce-9806-a37f1b10cf98', 'Every workspace belongs to exactly one project. It''s not optional and it isn''t a multi-membership relationship.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('afc252c6-b1f5-4c62-a559-14b50f6d4eb0', '784390a2-01f9-4b4a-b907-73754dd200f5', 12, 'What is the ''Default Project'' in an HCP Terraform organization?', 'Projects', 'Default Project', 'mcq');
VALUES ('afc252c6-b1f5-4c62-a559-14b50f6d4eb0', '63ba993d-3401-44d8-a8fb-5c7d375640c5', 'Every organization gets an auto-created Default Project; new workspaces land there unless assigned elsewhere, and while it can be renamed, it cannot be deleted.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('6446bf0a-c89c-4115-87c5-09d4716dc6a7', '784390a2-01f9-4b4a-b907-73754dd200f5', 13, 'Can HCP Terraform projects be nested inside one another (e.g. a ''child'' project inside a ''parent'' project) to model a team hierarchy?', 'Projects', 'No Nested Projects', 'mcq');
VALUES ('6446bf0a-c89c-4115-87c5-09d4716dc6a7', 'fd46dccf-6fdf-4d44-92f1-308fd1fc48a0', 'Projects sit at a single flat level under the organization — there''s no nested project hierarchy or automatic inheritance between projects.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('3f714422-fa0f-4fdf-bc97-b9feb1eb2653', '784390a2-01f9-4b4a-b907-73754dd200f5', 14, 'What is a direct consequence of moving an existing workspace from one project to another?', 'Projects', 'Moving a Workspace Between Projects', 'mcq');
VALUES ('3f714422-fa0f-4fdf-bc97-b9feb1eb2653', 'b5195f95-bec0-4280-b9c7-4d85b6c73e04', 'Because team access is commonly granted at the project level, moving a workspace to a different project can change which teams/users can read or write to it.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('d0b77466-29ac-464b-b3d4-1ac17bb5e40f', '784390a2-01f9-4b4a-b907-73754dd200f5', 15, 'A workspace''s execution-mode setting can be set to ''Project Default'' rather than explicitly Remote/Local/Agent. What does that mean?', 'Projects', 'Project-Level Execution Mode Default', 'mcq');
VALUES ('d0b77466-29ac-464b-b3d4-1ac17bb5e40f', '8a18fea3-275a-4ba4-8e27-3588f6d3d752', 'Setting a workspace''s execution mode to ''Project Default'' means it takes on the execution mode configured at the project level instead of pinning its own explicit value.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('87c97924-9033-402d-95af-ad7882722317', '784390a2-01f9-4b4a-b907-73754dd200f5', 16, 'What is a typical basis teams use for structuring their HCP Terraform projects?', 'Projects', 'Why Organize by Project', 'mcq');
VALUES ('87c97924-9033-402d-95af-ad7882722317', '5e56607b-5353-4214-be66-49b4a3fc97f2', 'HCP Terraform projects are a flexible grouping mechanism — teams typically structure them around organizational boundaries like team, business unit, or service ownership, not any fixed technical rule.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('00c1338c-eda8-4bbc-b1d7-6e3b10c9a766', '784390a2-01f9-4b4a-b907-73754dd200f5', 17, 'At what levels can cross-workspace state sharing be configured in HCP Terraform?', 'Projects', 'State Sharing Scope', 'mcq');
VALUES ('00c1338c-eda8-4bbc-b1d7-6e3b10c9a766', '1432a370-ee1d-4136-89b1-bd7df2bf19fe', 'HCP Terraform lets you configure state sharing access at the project level (workspaces within/across specific projects) or organization-wide, not just per individual workspace pair.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('11af784c-595c-41be-ab1e-3869d0ebe1a0', '784390a2-01f9-4b4a-b907-73754dd200f5', 18, 'Besides assigning a workspace to a project, HCP Terraform also lets you attach free-form tags to workspaces. What is one thing tags can be used for that project membership alone does not provide?', 'Projects', 'Project vs. Tag-Based Grouping', 'mcq');
VALUES ('11af784c-595c-41be-ab1e-3869d0ebe1a0', 'e75f72f5-2a94-40f7-8714-009257c2515a', 'Tags let you target configuration (like policy sets) at workspaces sharing a tag regardless of which project they''re in — a cross-cutting grouping that project membership (a single, exclusive assignment) doesn''t provide on its own.', 'Projects — Organizing Workspaces — authored from developer.hashicorp.com/terraform/cloud-docs/projects and .../tutorials/cloud/projects; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

-- ── Section: The Run Lifecycle (12 questions) — Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material. ──

VALUES ('92372697-826e-404c-be50-7aa562e20137', '784390a2-01f9-4b4a-b907-73754dd200f5', 19, 'Once a run has begun its plan stage in a workspace, what happens to any other run queued for that same workspace?', 'Run Lifecycle', 'Run Queue Behavior', 'mcq');
VALUES ('92372697-826e-404c-be50-7aa562e20137', 'd471ecf7-5c73-4e0b-a334-0eec9407cab6', 'A workspace processes one run''s plan/apply cycle before the next can proceed — a queued run has to wait until the current one reaches a confirmed/applied or discarded state.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('000d8127-1367-4802-a66e-905ee6f3e8f1', '784390a2-01f9-4b4a-b907-73754dd200f5', 20, 'What causes a run sitting in the ''Pending'' state to automatically move into the plan stage?', 'Run Lifecycle', 'Pending to Plan Transition', 'mcq');
VALUES ('000d8127-1367-4802-a66e-905ee6f3e8f1', 'b2fcb704-d185-43b4-b5de-5dcba6d95da2', 'A run automatically proceeds from pending into the plan stage once it''s first in the workspace''s queue — no manual action is needed to start planning.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('70f87fe1-50bc-4216-85ab-7083ba52820b', '784390a2-01f9-4b4a-b907-73754dd200f5', 21, 'In the documented run-stage sequence, where does an OPA policy check fall relative to cost estimation?', 'Run Lifecycle', 'OPA vs. Cost Estimation Ordering', 'mcq');
VALUES ('70f87fe1-50bc-4216-85ab-7083ba52820b', '14efc6c6-f37e-4c6c-9151-a79e4ef36970', 'Per the documented run-stage ordering, OPA policy checks occur before cost estimation, with Sentinel policy checks occurring after cost estimation.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('309a0408-2afb-4b87-8f06-6c7173414095', '784390a2-01f9-4b4a-b907-73754dd200f5', 22, 'In the documented run-stage sequence, where does a Sentinel policy check fall relative to cost estimation?', 'Run Lifecycle', 'Sentinel vs. Cost Estimation Ordering', 'mcq');
VALUES ('309a0408-2afb-4b87-8f06-6c7173414095', 'c46b63eb-7451-4a52-8fe1-837c93816cd3', 'The documented sequence runs cost estimation after any OPA check and before any Sentinel check — so Sentinel checks come after cost estimation, not before it.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('52395238-a13b-47f5-85f0-fb86e968859f', '784390a2-01f9-4b4a-b907-73754dd200f5', 23, 'A run''s plan fails a hard-mandatory (non-overridable) Sentinel policy. What happens to that run?', 'Run Lifecycle', 'Hard-Mandatory Policy Failure Effect', 'mcq');
VALUES ('52395238-a13b-47f5-85f0-fb86e968859f', '0025a679-4aa9-4af0-9f84-4d5316168a87', 'A hard-mandatory policy failure blocks the run outright — unlike soft-mandatory (overridable), there is no override path; the configuration itself has to change.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('46168f2f-a1aa-4390-b624-a2ca3f866ab7', '784390a2-01f9-4b4a-b907-73754dd200f5', 24, 'Which of the following is NOT a documented terminal/completion state for an HCP Terraform run?', 'Run Lifecycle', 'Run Completion States', 'mcq');
VALUES ('46168f2f-a1aa-4390-b624-a2ca3f866ab7', 'e56d8c45-cff9-4c12-b52c-98273d752560', 'Documented completion states include Applied, Planned and Finished, Plan/Apply Errored, Discarded, and Canceled — ''Suspended'' is not one of them.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('64e075c5-0335-4e18-bd30-7c0c5fcdf3bf', '784390a2-01f9-4b4a-b907-73754dd200f5', 25, 'After a plan completes and is awaiting confirmation, what does discarding it do, as opposed to confirming/applying it?', 'Run Lifecycle', 'Discard vs. Confirm', 'mcq');
VALUES ('64e075c5-0335-4e18-bd30-7c0c5fcdf3bf', 'f24fb3a6-738e-4b32-97f9-d5026eed1cc2', 'Discarding a completed plan simply abandons it without applying — the run ends, and the workspace becomes free to process its next queued run.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('3fe24188-ebf4-4af6-912f-57044f0c0a53', '784390a2-01f9-4b4a-b907-73754dd200f5', 26, 'Why can a speculative plan (e.g. one triggered by opening a pull request) never be applied directly?', 'Run Lifecycle', 'Speculative Plan Cannot Apply', 'mcq');
VALUES ('3fe24188-ebf4-4af6-912f-57044f0c0a53', '0de68491-dea8-45c9-9cf8-03587b1e2346', 'Speculative plans are preview-only by design — they show what would happen without creating an applyable run, which is exactly why they''re safe to run automatically against every pull request.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('2b88acae-7359-4cbf-9d71-d127535aeefa', '784390a2-01f9-4b4a-b907-73754dd200f5', 27, 'What is the purpose of a ''run trigger'' configured on an HCP Terraform workspace?', 'Run Lifecycle', 'Run Triggers Between Workspaces', 'mcq');
VALUES ('2b88acae-7359-4cbf-9d71-d127535aeefa', '490ea6a3-12fb-4906-ab2e-b650ac735dda', 'Run triggers connect workspaces so that a successful apply in one (source) workspace automatically queues a new run in another (dependent) workspace, useful for layered infrastructure.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('3301f989-9737-4db2-939d-1b36be173db1', '784390a2-01f9-4b4a-b907-73754dd200f5', 28, 'What happens during the ''fetching'' stage of a VCS-driven run, before planning begins?', 'Run Lifecycle', 'Fetching Stage', 'mcq');
VALUES ('3301f989-9737-4db2-939d-1b36be173db1', '87a2a306-052a-46a2-a0c0-52e905040f7f', 'The fetching stage retrieves the actual configuration (source code and referenced modules) from the linked VCS ref before Terraform can generate a plan from it.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('b154bfa7-3209-4876-86ac-7e7820844ec6', '784390a2-01f9-4b4a-b907-73754dd200f5', 29, 'HCP Terraform supports configurable run tasks (external integrations) that can execute at points like ''pre-plan'' or ''post-plan'' in the run stage sequence. What does this let an organization do?', 'Run Lifecycle', 'Pre-Plan / Post-Plan Run Tasks', 'mcq');
VALUES ('b154bfa7-3209-4876-86ac-7e7820844ec6', '7f190e92-37b7-437a-ae94-02ac7bab8145', 'Run tasks are extension points in the run lifecycle (pre-plan, post-plan, pre-apply, post-apply, etc.) that let external systems participate in or gate a run beyond HCP Terraform''s own built-in stages.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('74fe84d4-41a4-4d75-bd37-780e89fe1199', '784390a2-01f9-4b4a-b907-73754dd200f5', 30, 'How does a run ending in ''Errored'' differ from one ending in ''Discarded''?', 'Run Lifecycle', 'Errored vs. Discarded', 'mcq');
VALUES ('74fe84d4-41a4-4d75-bd37-780e89fe1199', '7e3d698d-9121-4a77-8cdf-0762c2ea6f9d', 'Errored reflects an actual operational failure during plan/apply; Discarded reflects a deliberate decision to abandon an otherwise-valid, successfully-completed plan without applying it.', 'Run Lifecycle — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/run/states and .../run/ui; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

-- ── Section: Policy Sets: Attaching Sentinel/OPA at Scale (8 questions) — Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material. ──

VALUES ('86a3ace9-0f72-485b-a3ba-364c7b4b05a1', '784390a2-01f9-4b4a-b907-73754dd200f5', 31, 'At which levels can an HCP Terraform policy set (Sentinel or OPA) be attached?', 'Policy Sets', 'Policy Set Attachment Levels', 'mcq');
VALUES ('86a3ace9-0f72-485b-a3ba-364c7b4b05a1', '9904794b-8421-46a5-b2c8-7b472a7652ae', 'Policy sets are flexible: they can be scoped globally, to specific projects, to specific workspaces, or to any workspace carrying a matching tag.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('f111bcf4-2f7f-4671-8980-2e9db728d095', '784390a2-01f9-4b4a-b907-73754dd200f5', 32, 'A policy set is attached with enforcement level ''advisory''. What happens if a run''s plan fails one of its policies?', 'Policy Sets', 'Advisory Enforcement Level', 'mcq');
VALUES ('f111bcf4-2f7f-4671-8980-2e9db728d095', '9a9764a5-a264-4abb-871e-9edeeb9fc077', 'Advisory is the least strict enforcement level: failed policies are purely informational and never stop the run from proceeding.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('02359144-0133-41f0-a37f-07edf197077c', '784390a2-01f9-4b4a-b907-73754dd200f5', 33, 'What distinguishes the ''mandatory overridable'' (soft-mandatory) enforcement level from hard-mandatory?', 'Policy Sets', 'Mandatory Overridable (Soft-Mandatory)', 'mcq');
VALUES ('02359144-0133-41f0-a37f-07edf197077c', '38a175d6-b213-4731-b99a-b6efaea24297', 'Mandatory overridable blocks the run by default (unlike advisory) but, unlike hard-mandatory, gives an appropriately-permissioned user an explicit path to override the failure and proceed.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('197d2eed-d23d-4ea2-a99b-2c0f322857ed', '784390a2-01f9-4b4a-b907-73754dd200f5', 34, 'What happens under the ''mandatory'' (hard-mandatory) enforcement level when a policy fails?', 'Policy Sets', 'Hard-Mandatory Enforcement', 'mcq');
VALUES ('197d2eed-d23d-4ea2-a99b-2c0f322857ed', '476f91a5-deff-4e05-8a6a-1bb1d9e945b2', 'Hard-mandatory is the strictest level — there''s no override mechanism at all; the run simply cannot proceed until the configuration itself changes to satisfy the policy.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('1c482202-6366-4b5d-a7a2-4eec72868e7f', '784390a2-01f9-4b4a-b907-73754dd200f5', 35, 'A globally-attached policy set shouldn''t apply to one specific workspace that has a legitimate reason to violate it. What can be done?', 'Policy Sets', 'Excluding a Workspace From a Policy Set', 'mcq');
VALUES ('1c482202-6366-4b5d-a7a2-4eec72868e7f', 'aad3a1ff-55fa-49b4-a20d-2618fa7adc71', 'Policy sets support explicit exclusions, letting you scope a broadly-attached (e.g. global) policy set away from specific workspaces, projects, or tags that shouldn''t be subject to it.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('dfe7ed96-be0f-4fdb-942e-2895fa54d563', '784390a2-01f9-4b4a-b907-73754dd200f5', 36, 'What is the benefit of attaching a policy set to workspaces matching a specific TAG, rather than attaching it per-project?', 'Policy Sets', 'Tag-Based Policy Attachment', 'mcq');
VALUES ('dfe7ed96-be0f-4fdb-942e-2895fa54d563', 'd8b536e6-c5e1-4699-aea4-f4791a792514', 'Since projects are a flat, exclusive grouping, tag-based policy attachment gives you a second, cross-cutting way to target workspaces sharing something in common (e.g. an environment or compliance need) regardless of project boundaries.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('73078097-d3a1-4731-8230-ebf0dbcdf0b6', '784390a2-01f9-4b4a-b907-73754dd200f5', 37, 'Why must a workspace generally use Remote (or Agent) execution mode, rather than Local, for its Sentinel/OPA policy checks to actually run?', 'Policy Sets', 'Policy Check Requires Remote Execution', 'mcq');
VALUES ('73078097-d3a1-4731-8230-ebf0dbcdf0b6', '5f655d05-9318-42c8-ad63-ec56f0fa9b97', 'Policy enforcement is a stage within HCP Terraform''s own managed run pipeline; local execution mode runs the actual Terraform operation on the practitioner''s machine, outside that pipeline, so the built-in policy-check stage doesn''t apply the same way.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');

VALUES ('e132e1ab-f10b-4986-9da7-8c377178a63a', '784390a2-01f9-4b4a-b907-73754dd200f5', 38, 'What is the relationship between a ''policy set'' and an individual Sentinel (or OPA) policy?', 'Policy Sets', 'Policy Sets vs. Sentinel Itself', 'mcq');
VALUES ('e132e1ab-f10b-4986-9da7-8c377178a63a', 'b55269d9-0a67-4679-9273-868d6fcbfbd3', 'A policy set bundles individual policies together as the deployable/attachable unit — you scope and enforce the set, not each policy file individually.', 'Policy Sets: Attaching Sentinel/OPA at Scale — authored from developer.hashicorp.com/terraform/cloud-docs/workspaces/policy-enforcement and .../workspaces/policy-enforcement/manage-policy-sets; verified via web search against current HCP Terraform docs, not copied from any official HashiCorp exam material.');
