INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes, positive_marks, negative_marks)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2ad45567-c7ea-4b3e-bdf7-1a15a80bcd6f', '15eabab5-07d0-4cd1-9157-9abc56090e20', 0, 'A webhook fires when new commits are merged/pushed to the linked branch of the workspace''s connected VCS repository, automatically queuing a run');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('401a650f-a108-4b16-8039-92bc2cf82fdd', '15eabab5-07d0-4cd1-9157-9abc56090e20', 1, 'A practitioner must always manually click ''Queue Run'' in the UI, even with a VCS repository linked');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('09a9a262-9f9a-410c-9372-44240cb8917c', '15eabab5-07d0-4cd1-9157-9abc56090e20', 2, 'The workspace polls the VCS repository for changes once every 24 hours');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ca142a85-7222-4ea0-836f-31e9c8694b35', '15eabab5-07d0-4cd1-9157-9abc56090e20', 3, 'A run only starts if a Terraform Cloud administrator manually approves the connection each time');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('78e6d29b-3b0f-48eb-979d-c11a78b6ba52', '52d146fb-ad37-4533-b35e-f7fb514b3b05', 0, 'HCP Terraform runs a speculative plan and posts a link to it on the pull request, re-running the plan if the PR is updated — this never applies changes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7fe415ac-d5c5-42aa-a550-a16c2ca01c4c', '52d146fb-ad37-4533-b35e-f7fb514b3b05', 1, 'HCP Terraform immediately applies the PR''s changes to production');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2b3e1c77-ed45-4029-b5ec-8da4eab1e3a2', '52d146fb-ad37-4533-b35e-f7fb514b3b05', 2, 'Nothing happens until the PR is merged; pull requests have no effect on runs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('eafbc46f-07ad-42ed-9224-49a003f791bf', '52d146fb-ad37-4533-b35e-f7fb514b3b05', 3, 'The workspace is automatically deleted and recreated for each PR');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0f3806b4-e0d2-43aa-bf0c-52c5ceb1e3a5', '954b5b3f-9be1-43eb-b0d6-45947ffc68dc', 0, 'Remotely in HCP Terraform (assuming remote execution mode) — the CLI streams progress back to the terminal, but the run itself executes on HCP Terraform''s infrastructure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('02f5abd5-7aae-47c9-9f9d-2f9b08df7cb8', '954b5b3f-9be1-43eb-b0d6-45947ffc68dc', 1, 'Always on the practitioner''s own local machine, identical to not using HCP Terraform at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20a9c807-22df-4512-a8b2-3de34b5e9956', '954b5b3f-9be1-43eb-b0d6-45947ffc68dc', 2, 'On a dedicated node the practitioner must provision and register themselves, with no HCP Terraform involvement');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9811aa69-a856-4390-9c3f-3dcd559e85b2', '954b5b3f-9be1-43eb-b0d6-45947ffc68dc', 3, 'In the practitioner''s web browser via WebAssembly');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ffa3f0ba-7cbc-4994-9ef7-fc50de9d6b5c', '79acff84-f8f5-4b65-82de-10dfb2f0a082', 0, 'Authenticate via ''terraform login'', and configure a ''cloud'' block in the Terraform configuration pointing at the organization/workspace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d889a17-fd48-4869-8b3b-a5bea0956530', '79acff84-f8f5-4b65-82de-10dfb2f0a082', 1, 'Install a special CLI-only binary that replaces the standard ''terraform'' executable entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('269c9753-33ea-4367-bc73-199ae6e288bb', '79acff84-f8f5-4b65-82de-10dfb2f0a082', 2, 'Create an SSH key pair and register its public key with the workspace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('80cf3d04-e827-41a1-910f-1283dcb03174', '79acff84-f8f5-4b65-82de-10dfb2f0a082', 3, 'Enable ''terraform workspace new'' for every environment, since CLI-driven workspaces require CLI workspaces to be created first');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ebcbf80a-5403-4f87-8721-9f03c0af9a04', '158c5edf-a4b2-495a-9368-256dae1faf53', 0, 'Runs are created directly via calls to the HCP Terraform API — it''s the most flexible option but requires building custom tooling/automation around those API calls, unlike the other two which have built-in trigger mechanisms');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e99c097f-b48b-4d2f-aeca-e1cec03f214f', '158c5edf-a4b2-495a-9368-256dae1faf53', 1, 'It is functionally identical to the VCS-driven workflow, just using a different name');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc131d41-2a0d-49b2-8b11-0cb5f6031732', '158c5edf-a4b2-495a-9368-256dae1faf53', 2, 'It''s the only workflow type that supports Sentinel policy checks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3180c103-a223-4258-9636-54acb9ddd961', '158c5edf-a4b2-495a-9368-256dae1faf53', 3, 'It requires disabling remote state storage for the workspace');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('991fe087-2038-4292-8c08-879f7222e62a', 'd50ab5c0-ee23-45b5-8720-724e9e9f7cf4', 0, 'HCP Terraform performs the actual Terraform runs on its own disposable virtual machines — this is what enables features like policy checks and cost estimation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4b362911-ed46-470f-9766-30d123912955', 'd50ab5c0-ee23-45b5-8720-724e9e9f7cf4', 1, 'Terraform always runs on the practitioner''s laptop, with only the final state uploaded afterward');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6efb5314-1a90-45dc-bb30-5fa92452943a', 'd50ab5c0-ee23-45b5-8720-724e9e9f7cf4', 2, 'The workspace has no state storage at all and recomputes everything from scratch on every run');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ab4d876-08df-4ff8-8b2b-277729319c91', 'd50ab5c0-ee23-45b5-8720-724e9e9f7cf4', 3, 'It refers exclusively to workspaces connected via the API-driven workflow');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e090a5a9-21c4-4b19-8a9a-20e510970999', 'e7b36919-0088-43f4-ba51-b5bd3c7c148a', 0, 'HCP Terraform does not evaluate that workspace''s variables or variable sets during local execution — the practitioner''s own local values/CLI flags are what actually apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('af00d09d-b662-4f2c-87ff-8ba731a4f4c9', 'e7b36919-0088-43f4-ba51-b5bd3c7c148a', 1, 'Local execution mode disables remote state storage entirely, forcing state to live only on the practitioner''s disk');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b0d8b93f-170e-46a6-a313-c2c9e3bb52a6', 'e7b36919-0088-43f4-ba51-b5bd3c7c148a', 2, 'Local execution mode is only available to organizations on the free tier');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96c54eb1-7734-4eed-9a24-2133ee35cd0e', 'e7b36919-0088-43f4-ba51-b5bd3c7c148a', 3, 'Local execution mode cannot be used with the CLI-driven workflow at all');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6eb7ac6e-665e-4b2b-b246-465deb5e270b', '94cfa129-b835-4922-96f6-bc85b721cffe', 0, 'It lets HCP Terraform run operations via a lightweight, self-hosted HCP Terraform Agent, typically for infrastructure in an isolated or private network HCP Terraform''s own cloud runners can''t directly reach');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('941f208f-5d15-4907-b555-a2ce5bd535aa', '94cfa129-b835-4922-96f6-bc85b721cffe', 1, 'It automatically converts the workspace to use CLI workspaces internally');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2f81428f-acd2-4133-a735-5747c92f9091', '94cfa129-b835-4922-96f6-bc85b721cffe', 2, 'It is a synonym for the API-driven workflow');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b93f93a2-803a-4172-8617-3070082cb324', '94cfa129-b835-4922-96f6-bc85b721cffe', 3, 'It disables policy checks to speed up runs in high-throughput pipelines');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f205d706-4821-463e-ada6-90974d2c9a58', '92c6e83b-5bb9-4817-a3c0-88da156f3f8f', 0, 'A CLI-driven apply requires the practitioner to explicitly pass ''-auto-approve'' to skip confirmation, while UI- and API-triggered runs instead respect whatever auto-apply setting is configured on the workspace itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e97ce2ef-f35a-47d7-9edd-7b07d028dacd', '92c6e83b-5bb9-4817-a3c0-88da156f3f8f', 1, 'Auto-apply is impossible in the CLI-driven workflow under any circumstances');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('00c179c4-c8b1-4b43-a572-3c8cad2b3d93', '92c6e83b-5bb9-4817-a3c0-88da156f3f8f', 2, 'The workspace''s auto-apply setting applies identically and automatically to every workflow type with no CLI flag needed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9b7b32db-aa1c-4941-87d2-80a934436ba9', '92c6e83b-5bb9-4817-a3c0-88da156f3f8f', 3, 'Only VCS-driven workspaces support any form of auto-apply; CLI and API workspaces always require manual confirmation regardless of settings');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee4869b8-6456-495b-806a-5e3762343a1d', 'a1a73aaf-a152-431c-ae6d-da91c247ee17', 0, 'API-driven — runs are created via direct calls to the HCP Terraform API from the team''s own tooling');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('525b4462-3900-42b2-912e-90cfcfe83d1f', 'a1a73aaf-a152-431c-ae6d-da91c247ee17', 1, 'VCS-driven — because any automation should go through a Git webhook regardless of the actual trigger source');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05e0ce99-88fd-46f4-b987-f73b9fb40d4d', 'a1a73aaf-a152-431c-ae6d-da91c247ee17', 2, 'CLI-driven — because it''s the most automation-friendly by default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b853887b-2eee-4005-b538-5eb8103f0320', 'a1a73aaf-a152-431c-ae6d-da91c247ee17', 3, 'None of the three workflow types support this use case; it requires Terraform Enterprise specifically');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('75a49c5c-a6da-4cce-9806-a37f1b10cf98', '73b5c2c3-b9aa-4b7e-b540-75cf037f718a', 0, 'Exactly one — every workspace in an organization belongs to exactly one project');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70891108-9b96-4055-925b-7253adf33bb2', '73b5c2c3-b9aa-4b7e-b540-75cf037f718a', 1, 'Zero or more; a workspace can exist without being in any project');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9176440-9354-47d9-a2f0-3d5ad7e66067', '73b5c2c3-b9aa-4b7e-b540-75cf037f718a', 2, 'Up to three, to allow shared visibility across teams');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e79e002e-4e1a-423e-9b38-5a31f6ab5bf6', '73b5c2c3-b9aa-4b7e-b540-75cf037f718a', 3, 'As many as the organization has, since project membership is workspace-independent');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63ba993d-3401-44d8-a8fb-5c7d375640c5', 'afc252c6-b1f5-4c62-a559-14b50f6d4eb0', 0, 'A project HCP Terraform automatically creates for every organization, which existing/unassigned workspaces belong to by default — it can be renamed but not deleted');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f02bd8db-53ab-439c-9260-411deb245534', 'afc252c6-b1f5-4c62-a559-14b50f6d4eb0', 1, 'An optional project a workspace administrator must manually create before any workspaces can exist');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e27122e1-b529-4694-b61d-5d1b66fd737d', 'afc252c6-b1f5-4c62-a559-14b50f6d4eb0', 2, 'A project that only contains example/demo workspaces provided by HashiCorp');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e3da2aa2-413f-4d6d-9ba1-f8c88230dd74', 'afc252c6-b1f5-4c62-a559-14b50f6d4eb0', 3, 'A project reserved exclusively for the organization''s billing and usage settings');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fd46dccf-6fdf-4d44-92f1-308fd1fc48a0', '6446bf0a-c89c-4115-87c5-09d4716dc6a7', 0, 'No — HCP Terraform''s project structure is flat; all projects exist directly under the organization with no parent-child nesting or inheritance between projects');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b96cfb73-d83f-4be8-ad87-194c9e981a2c', '6446bf0a-c89c-4115-87c5-09d4716dc6a7', 1, 'Yes, projects can be nested up to 5 levels deep');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2471a1a9-7935-447f-b5ab-4e75949fbb3e', '6446bf0a-c89c-4115-87c5-09d4716dc6a7', 2, 'Yes, but only on Terraform Enterprise, not HCP Terraform''s SaaS offering');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3df94b49-9cd4-47fc-875f-283e36199a4b', '6446bf0a-c89c-4115-87c5-09d4716dc6a7', 3, 'Yes, nesting is unlimited and is the primary way permissions are inherited');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5195f95-bec0-4280-b9c7-4d85b6c73e04', '3f714422-fa0f-4fdf-bc97-b9feb1eb2653', 0, 'It can change who has read/write access to that workspace, since team permissions are frequently granted at the project level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff5819f5-4529-4ecf-9e4f-6e1823f036ab', '3f714422-fa0f-4fdf-bc97-b9feb1eb2653', 1, 'The workspace''s Terraform state is permanently wiped and must be re-imported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b650605-ee08-489e-be7b-a5df6865cfbb', '3f714422-fa0f-4fdf-bc97-b9feb1eb2653', 2, 'All variable values configured on the workspace are automatically reset to their defaults');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aeff8fc1-2ff2-4f07-a96f-e4ce5a2f23b4', '3f714422-fa0f-4fdf-bc97-b9feb1eb2653', 3, 'The workspace''s workflow type (VCS/CLI/API-driven) is forcibly reset to VCS-driven');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8a18fea3-275a-4ba4-8e27-3588f6d3d752', 'd0b77466-29ac-464b-b3d4-1ac17bb5e40f', 0, 'The workspace inherits whatever default execution mode is configured on the project it belongs to, rather than specifying its own override');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d746b53d-6331-4186-8b4a-c19bc166bede', 'd0b77466-29ac-464b-b3d4-1ac17bb5e40f', 1, 'The workspace falls back to Local execution mode automatically, since that''s always the project default');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6f42452c-8b95-4ea6-bdd2-b684948295e7', 'd0b77466-29ac-464b-b3d4-1ac17bb5e40f', 2, 'It disables execution entirely until an administrator manually assigns a mode');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a4b4526-e584-4300-af69-aef516213366', 'd0b77466-29ac-464b-b3d4-1ac17bb5e40f', 3, '''Project Default'' only applies to workspaces created via the API-driven workflow');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e56607b-5353-4214-be66-49b4a3fc97f2', '87c97924-9033-402d-95af-ad7882722317', 0, 'Grouping workspaces by organizational unit, such as by team, business unit, or service, to align with how resource usage/ownership is actually structured');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84274baf-fc84-4a89-af5a-50a0b0a47cb8', '87c97924-9033-402d-95af-ad7882722317', 1, 'Projects must correspond 1:1 with individual AWS/Azure/GCP accounts, with no other grouping allowed');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3460b80f-0bf0-4ae7-83fa-ac51384965c3', '87c97924-9033-402d-95af-ad7882722317', 2, 'Projects are auto-generated per Terraform version in use and cannot be organized manually');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bcf45b55-03e2-4b41-979b-fd5f44280e8f', '87c97924-9033-402d-95af-ad7882722317', 3, 'Projects must be named after the Terraform module registry namespace they consume');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1432a370-ee1d-4136-89b1-bd7df2bf19fe', '00c1338c-eda8-4bbc-b1d7-6e3b10c9a766', 0, 'At the project level or the organization level');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f4ef19a-a456-4046-a169-22e87905120b', '00c1338c-eda8-4bbc-b1d7-6e3b10c9a766', 1, 'Only at the individual workspace level, never more broadly');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04c4acd0-93ad-4250-aa3f-c7278acfc7ff', '00c1338c-eda8-4bbc-b1d7-6e3b10c9a766', 2, 'Only globally across the entire organization, with no per-project option');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5acbb55-48d0-4f11-9d78-8f2a4a787a84', '00c1338c-eda8-4bbc-b1d7-6e3b10c9a766', 3, 'State sharing is not a configurable concept in HCP Terraform');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e75f72f5-2a94-40f7-8714-009257c2515a', '11af784c-595c-41be-ab1e-3869d0ebe1a0', 0, 'Attaching a policy set (or other org-level configuration) to every workspace matching a given tag, cutting across project boundaries');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6d6fdb6-450e-4e2e-8876-822718034713', '11af784c-595c-41be-ab1e-3869d0ebe1a0', 1, 'Tags are purely cosmetic labels shown in the UI with no functional effect anywhere in HCP Terraform');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1a595bd1-09f1-4fd6-908c-c9fb02714cac', '11af784c-595c-41be-ab1e-3869d0ebe1a0', 2, 'Tags replace projects entirely as of the current HCP Terraform version');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4315229-80a0-4661-b1c4-ebd98871e8de', '11af784c-595c-41be-ab1e-3869d0ebe1a0', 3, 'Only one tag can ever be applied per workspace, unlike project membership');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d471ecf7-5c73-4e0b-a334-0eec9407cab6', '92372697-826e-404c-be50-7aa562e20137', 0, 'It waits — until the current run''s plan is confirmed/applied or discarded, HCP Terraform won''t start another run in that workspace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cc95227a-f6ef-4c27-82e3-640c1fafc854', '92372697-826e-404c-be50-7aa562e20137', 1, 'It runs concurrently alongside the first, since HCP Terraform allows unlimited parallel runs per workspace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3ded398e-672f-4afd-b41e-152d5e5ecf92', '92372697-826e-404c-be50-7aa562e20137', 2, 'It''s automatically canceled the moment a newer run is queued');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dbf0796e-d128-47d1-bd65-85a9419b25d3', '92372697-826e-404c-be50-7aa562e20137', 3, 'It''s redirected to execute against a different, automatically-created workspace');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b2fcb704-d185-43b4-b5de-5dcba6d95da2', '000d8127-1367-4802-a66e-905ee6f3e8f1', 0, 'Being first in that workspace''s run queue — HCP Terraform proceeds automatically to plan once nothing else is ahead of it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0f45f01-b1db-47be-a652-07f2d7483516', '000d8127-1367-4802-a66e-905ee6f3e8f1', 1, 'A human must manually click ''Start Plan'' for every single run, with no automatic progression');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7ee44e6-635a-482d-b578-adc23a7a5de2', '000d8127-1367-4802-a66e-905ee6f3e8f1', 2, 'The workspace''s linked VCS repository must first pass its CI checks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7621562b-61d4-41e5-8d83-e1676dae7c8e', '000d8127-1367-4802-a66e-905ee6f3e8f1', 3, 'Pending runs only advance once a Sentinel policy set has been manually approved');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('14efc6c6-f37e-4c6c-9151-a79e4ef36970', '70f87fe1-50bc-4216-85ab-7083ba52820b', 0, 'OPA policy checks run before cost estimation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('954adc18-f090-4f74-9b5d-65fc79a5567c', '70f87fe1-50bc-4216-85ab-7083ba52820b', 1, 'OPA policy checks run after cost estimation but before Sentinel checks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a40dad6f-8dd3-4a16-a11b-efadcd77549d', '70f87fe1-50bc-4216-85ab-7083ba52820b', 2, 'OPA and cost estimation always run in parallel, never sequentially');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('de9a98a5-51c5-4b85-ad8c-1fe005f4e285', '70f87fe1-50bc-4216-85ab-7083ba52820b', 3, 'OPA policy checks only run after the apply stage completes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c46b63eb-7451-4a52-8fe1-837c93816cd3', '309a0408-2afb-4b87-8f06-6c7173414095', 0, 'Sentinel policy checks run after cost estimation');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ccd001dd-d1f3-4af2-b68b-6129da9eee45', '309a0408-2afb-4b87-8f06-6c7173414095', 1, 'Sentinel policy checks run before cost estimation, ahead of OPA checks');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df5920b8-1b3c-4cbc-a099-db1ccc34aef8', '309a0408-2afb-4b87-8f06-6c7173414095', 2, 'Sentinel checks replace cost estimation entirely whenever both are enabled');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('12e87f80-e7b0-4f15-9e25-b07a1293f58b', '309a0408-2afb-4b87-8f06-6c7173414095', 3, 'Sentinel checks only run during the apply stage, never before it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0025a679-4aa9-4af0-9f84-4d5316168a87', '52395238-a13b-47f5-85f0-fb86e968859f', 0, 'The run cannot proceed to apply; a user must fix the underlying configuration issue that caused the failure before a new, passing run can be applied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e962acc2-5e48-496a-b565-69af01a31908', '52395238-a13b-47f5-85f0-fb86e968859f', 1, 'The run proceeds to apply anyway, but with the failing resources removed automatically');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d2a1feab-398d-411e-af5a-f89760780832', '52395238-a13b-47f5-85f0-fb86e968859f', 2, 'Any organization owner can click a single button to override the failure and continue, exactly like a soft-mandatory failure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e9693de9-7067-43d3-a21a-4d5a8c74ab91', '52395238-a13b-47f5-85f0-fb86e968859f', 3, 'The failure is only shown as a warning banner, with apply proceeding normally');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e56d8c45-cff9-4c12-b52c-98273d752560', '46168f2f-a1aa-4390-b624-a2ca3f866ab7', 0, 'Suspended');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc829f2f-a8c2-4753-ae49-89754111277c', '46168f2f-a1aa-4390-b624-a2ca3f866ab7', 1, 'Applied');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8df9be42-8b34-4629-81db-cc6b48d74274', '46168f2f-a1aa-4390-b624-a2ca3f866ab7', 2, 'Discarded');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('13a6a53f-d950-4756-9bcf-33021a179ed6', '46168f2f-a1aa-4390-b624-a2ca3f866ab7', 3, 'Errored');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f24fb3a6-738e-4b32-97f9-d5026eed1cc2', '64e075c5-0335-4e18-bd30-7c0c5fcdf3bf', 0, 'Discarding ends that run without applying its changes, freeing the workspace to start its next queued run — the planned changes are simply never carried out');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b218b5fd-d416-4249-8021-247386978b82', '64e075c5-0335-4e18-bd30-7c0c5fcdf3bf', 1, 'Discarding permanently deletes the workspace itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a49879e8-7d66-421d-9774-0a4eb0f5fc17', '64e075c5-0335-4e18-bd30-7c0c5fcdf3bf', 2, 'Discarding automatically re-plans with a completely different configuration version');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4d3d7f41-8a36-49bb-96ad-cdae6053fe8e', '64e075c5-0335-4e18-bd30-7c0c5fcdf3bf', 3, 'Discarding is only possible for VCS-driven runs, never CLI- or API-driven ones');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0de68491-dea8-45c9-9cf8-03587b1e2346', '3fe24188-ebf4-4af6-912f-57044f0c0a53', 0, 'Speculative plans exist purely to preview likely changes; they are not tied to a confirmable run that can proceed to an apply stage');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f28aac18-8975-42a0-a8c1-eb076760d038', '3fe24188-ebf4-4af6-912f-57044f0c0a53', 1, 'Speculative plans are technically identical to normal plans, but HCP Terraform enforces an arbitrary 24-hour delay before allowing apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69da59f9-d53e-4e41-aea4-81467fc50897', '3fe24188-ebf4-4af6-912f-57044f0c0a53', 2, 'Speculative plans require a separate Enterprise license feature to unlock the apply button');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3dda44e6-e06f-4bf1-ba43-3de4faf692e8', '3fe24188-ebf4-4af6-912f-57044f0c0a53', 3, 'Speculative plans can be applied, but only by an organization owner, never a regular member');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('490ea6a3-12fb-4906-ab2e-b650ac735dda', '2b88acae-7359-4cbf-9d71-d127535aeefa', 0, 'It automatically queues a new run in this workspace whenever a specified SOURCE workspace successfully applies, letting downstream workspaces react to upstream infrastructure changes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52ea5e46-204b-49c9-b018-e552625b042d', '2b88acae-7359-4cbf-9d71-d127535aeefa', 1, 'It restricts which VCS branches are allowed to trigger runs in this workspace');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2baffaf1-6427-47b8-a3de-9ecaf052f24e', '2b88acae-7359-4cbf-9d71-d127535aeefa', 2, 'It configures the specific virtual machine size used to execute the workspace''s runs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3dd4e947-1b1a-4c91-9237-652a5b03fe4b', '2b88acae-7359-4cbf-9d71-d127535aeefa', 3, 'It sets the maximum number of retries for a failed apply');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87a2a306-052a-46a2-a0c0-52e905040f7f', '3301f989-9737-4db2-939d-1b36be173db1', 0, 'HCP Terraform retrieves the relevant configuration content (and any required modules) from the linked VCS repository at the commit/ref that triggered the run');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0b4e95e7-8cf9-42d8-ab3f-d86e609c434a', '3301f989-9737-4db2-939d-1b36be173db1', 1, 'HCP Terraform downloads the entire prior state history for auditing purposes');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d1442a4-8d1a-45cc-b056-c4c27688923e', '3301f989-9737-4db2-939d-1b36be173db1', 2, 'HCP Terraform fetches billing information to confirm the organization''s subscription is current');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('70a85a35-4858-4e8e-b6f6-f9d406f34b2a', '3301f989-9737-4db2-939d-1b36be173db1', 3, 'Fetching only applies to API-driven runs, never VCS-driven ones');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7f190e92-37b7-437a-ae94-02ac7bab8145', 'b154bfa7-3209-4876-86ac-7e7820844ec6', 0, 'Hook custom external checks or integrations into specific points of the run lifecycle, beyond just the built-in cost-estimation/policy-check stages');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6efb9e3c-e983-4c9d-a810-0df1fce2e418', 'b154bfa7-3209-4876-86ac-7e7820844ec6', 1, 'Replace the plan stage entirely with a fully custom, HCP-Terraform-independent process');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9dea58d-c507-4140-b48a-b94f16156e9c', 'b154bfa7-3209-4876-86ac-7e7820844ec6', 2, 'Only affect runs triggered by the CLI-driven workflow, never VCS- or API-driven runs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('52baba04-0eb1-4da7-8f13-5e0b3f8a9288', 'b154bfa7-3209-4876-86ac-7e7820844ec6', 3, 'Run arbitrary Terraform destroy operations automatically before every plan');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e3d698d-9121-4a77-8cdf-0762c2ea6f9d', '74fe84d4-41a4-4d75-bd37-780e89fe1199', 0, 'Errored means the plan or apply operation itself failed due to a problem (e.g. a provider error or invalid configuration); Discarded means a user deliberately chose not to proceed with an otherwise-successful plan');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d9d4e7a-10cc-46e0-9f45-ab447d630d08', '74fe84d4-41a4-4d75-bd37-780e89fe1199', 1, 'They are two names for exactly the same outcome, used interchangeably in the HCP Terraform UI');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('66b5cd5a-a91e-405a-aa67-df021c549c4b', '74fe84d4-41a4-4d75-bd37-780e89fe1199', 2, 'Errored only applies to CLI-driven runs; Discarded only applies to VCS-driven runs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('04e6f5a2-0d05-4e08-9a9a-9bb067128ba0', '74fe84d4-41a4-4d75-bd37-780e89fe1199', 3, 'Discarded means the run failed a policy check; Errored means a user manually canceled it');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9904794b-8421-46a5-b2c8-7b472a7652ae', '86a3ace9-0f72-485b-a3ba-364c7b4b05a1', 0, 'Globally across the whole organization, to specific projects, to specific workspaces, or to workspaces matching a specific tag');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('96385f0e-8f68-4a6f-b4f4-8877078a975f', '86a3ace9-0f72-485b-a3ba-364c7b4b05a1', 1, 'Only at the individual workspace level — organization-wide or project-wide policy attachment isn''t supported');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('03db024d-9de4-4d90-bd73-70873ed5a44e', '86a3ace9-0f72-485b-a3ba-364c7b4b05a1', 2, 'Only at the organization level; per-workspace exceptions aren''t possible');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c4b191d-1866-4ea5-b9ba-f65c8b93588d', '86a3ace9-0f72-485b-a3ba-364c7b4b05a1', 3, 'Only to CLI-driven workspaces, since VCS/API-driven runs bypass policy checks entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a9764a5-a264-4abb-871e-9edeeb9fc077', 'f111bcf4-2f7f-4671-8980-2e9db728d095', 0, 'The run is never interrupted — the failure is shown as informational in the UI, and the run proceeds regardless');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5a61cd33-5b97-4b16-9bdd-14371362b09b', 'f111bcf4-2f7f-4671-8980-2e9db728d095', 1, 'The run is blocked exactly like a hard-mandatory failure');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b5a172db-ac0b-43e7-bc52-b287be63c927', 'f111bcf4-2f7f-4671-8980-2e9db728d095', 2, 'The run is blocked, but any user (regardless of permissions) can override it');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d99ac0d-6cec-42a6-b7f3-28a9517a4c4b', 'f111bcf4-2f7f-4671-8980-2e9db728d095', 3, 'Advisory failures automatically roll back any changes already applied');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('38a175d6-b213-4731-b99a-b6efaea24297', '02359144-0133-41f0-a37f-07edf197077c', 0, 'A soft-mandatory failure stops the run by default, but a user with sufficient permissions can explicitly override it and let the run continue');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c8e68d99-dd32-4f6b-8c88-151acc812d34', '02359144-0133-41f0-a37f-07edf197077c', 1, 'Soft-mandatory failures are purely informational, identical to advisory');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee54921c-bc78-40ad-b1f1-3e5b8f4fe660', '02359144-0133-41f0-a37f-07edf197077c', 2, 'Soft-mandatory is only available for OPA policies, never for Sentinel policies');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a71ace66-901a-4ed9-8234-9ebd5f0644b1', '02359144-0133-41f0-a37f-07edf197077c', 3, 'Soft-mandatory automatically retries the plan with different inputs until it passes');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('476f91a5-deff-4e05-8a6a-1bb1d9e945b2', '197d2eed-d23d-4ea2-a99b-2c0f322857ed', 0, 'The run is blocked outright with no override option — the underlying issue must actually be fixed before the run (or a new run) can proceed to apply');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('387c89a3-e120-4d0c-bdde-bd5fd21e7d7c', '197d2eed-d23d-4ea2-a99b-2c0f322857ed', 1, 'It behaves identically to advisory, just with a different label in the UI');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3978c953-bf55-4d3f-8925-51f9bb484fd7', '197d2eed-d23d-4ea2-a99b-2c0f322857ed', 2, 'It can still be overridden, but only by an organization owner');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7239b52a-2b34-4102-a810-379ee1acfeae', '197d2eed-d23d-4ea2-a99b-2c0f322857ed', 3, 'It only applies to Sentinel policies; OPA has no equivalent hard-mandatory level');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aad3a1ff-55fa-49b4-a20d-2618fa7adc71', '1c482202-6366-4b5d-a7a2-4eec72868e7f', 0, 'That workspace (or project, or tag) can be explicitly excluded from the policy set''s scope');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd7af28d-7978-42fc-b7e5-30fbe07971c8', '1c482202-6366-4b5d-a7a2-4eec72868e7f', 1, 'Nothing — a globally-attached policy set cannot have any exceptions carved out');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d8952a4-22f7-40fa-9ac1-42ee30069a92', '1c482202-6366-4b5d-a7a2-4eec72868e7f', 2, 'The entire policy set must be deleted and recreated without global scope');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('18b50f88-44cf-44a7-be9a-0300eb447010', '1c482202-6366-4b5d-a7a2-4eec72868e7f', 3, 'The workspace must be moved out of the organization entirely to escape a global policy set');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d8b536e6-c5e1-4699-aea4-f4791a792514', 'dfe7ed96-be0f-4fdb-942e-2895fa54d563', 0, 'It lets the policy apply across workspaces that share a characteristic regardless of which project each one belongs to, cutting across the project-based grouping');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f9753a2e-3a50-46a1-a1cd-b5060be2e21a', 'dfe7ed96-be0f-4fdb-942e-2895fa54d563', 1, 'Tag-based attachment is strictly less flexible and exists only for backward compatibility with older HCP Terraform versions');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7052eaed-4c7e-4bf6-a868-79cd2e528998', 'dfe7ed96-be0f-4fdb-942e-2895fa54d563', 2, 'Tags can only be used with OPA policies, never Sentinel');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('06ca2b43-0797-46f4-8cf4-2602fea98b8f', 'dfe7ed96-be0f-4fdb-942e-2895fa54d563', 3, 'Tag-based attachment removes the need for enforcement levels entirely');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f655d05-9318-42c8-ad63-ec56f0fa9b97', '73078097-d3a1-4731-8230-ebf0dbcdf0b6', 0, 'Because policy checks are evaluated as part of HCP Terraform''s own managed run pipeline, which local execution mode bypasses by running the operation on the practitioner''s own machine instead');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('321d38c3-65f9-45ec-bf17-2dfa79d98c90', '73078097-d3a1-4731-8230-ebf0dbcdf0b6', 1, 'Because Local execution mode is fundamentally incompatible with having any state stored in HCP Terraform at all');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4ec23969-b392-4e56-badf-e82c323514b9', '73078097-d3a1-4731-8230-ebf0dbcdf0b6', 2, 'Because Sentinel and OPA are only licensed for use on Terraform Enterprise, not any HCP Terraform execution mode');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ab108b2-af2f-4ef6-b0f9-7db39edbcaa8', '73078097-d3a1-4731-8230-ebf0dbcdf0b6', 3, 'There is no such requirement; policy checks run identically regardless of execution mode');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b55269d9-0a67-4679-9273-868d6fcbfbd3', 'e132e1ab-f10b-4986-9da7-8c377178a63a', 0, 'A policy set is a collection that groups one or more individual policies together so they can be deployed and scoped (to workspaces/projects/tags/org) as a unit');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7bd81f8-ffa7-4655-ac51-bf857a31e0e1', 'e132e1ab-f10b-4986-9da7-8c377178a63a', 1, 'A policy set and a policy are the exact same object, just referred to by two different names in the UI vs. the API');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53f8469b-01e0-46a4-9cc0-fd7df51c6b85', 'e132e1ab-f10b-4986-9da7-8c377178a63a', 2, 'A policy set can only ever contain exactly one policy');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ac54a328-31a7-4e9a-a2c4-0eac38d1b1cb', 'e132e1ab-f10b-4986-9da7-8c377178a63a', 3, 'Policy sets are a Sentinel-only concept; OPA policies cannot be grouped into policy sets at all');
